		Receiver: "B", Destination: "M", HandoverTime: now,
	}); err != nil {
		t.Fatalf("initiate: %v", err)
	}
	recv := now.Add(time.Hour)
	const n = 20
	var wg sync.WaitGroup
	results := make([]*HandoverView, n)
	errs := make([]error, n)
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			results[i], errs[i] = s.ConfirmHandover("H1", "B", "M", recv)
